// mapped finds r in the runs and returns what it maps to, or r.
static int32_t mapped(const tk_case_run *runs, int64_t n, int32_t r) {
    int64_t lo = 0, hi = n;
    while (lo < hi) {
        int64_t m = lo + (hi - lo) / 2;
        if (r > runs[m].hi) {
            lo = m + 1;
        } else if (r < runs[m].lo) {
            hi = m;
        } else {
            return (r - runs[m].lo) % runs[m].stride == 0 ? r + runs[m].delta : r;
        }
    }

    return r;
}

int32_t tk_rune_upper(int32_t r) {
    if (r < 0x80) {
        return r >= 'a' && r <= 'z' ? r - 32 : r;
    }

    return mapped(upper, sizeof upper / sizeof upper[0], r);
}

int32_t tk_rune_lower(int32_t r) {
    if (r < 0x80) {
        return r >= 'A' && r <= 'Z' ? r + 32 : r;
    }

    return mapped(lower, sizeof lower / sizeof lower[0], r);
}

bool tk_rune_space(int32_t r) {
    if (r < 0x80) {
        return r == ' ' || (r >= '\t' && r <= '\r');
    }

    for (size_t i = 0; i < sizeof spaces / sizeof spaces[0]; i++) {
        if (spaces[i] == r) {
            return true;
        }
    }

    return false;
}

bool tk_isprint(int32_t r) {
    if (r < 0x80) {
        return r >= 0x20 && r < 0x7F;
    }

    int64_t lo = 0, hi = (int64_t)(sizeof printable / sizeof printable[0]) - 1;
    while (lo <= hi) {
        int64_t mid = (lo + hi) / 2;
        if (r < printable[mid][0]) {
            hi = mid - 1;
        } else if (r > printable[mid][1]) {
            lo = mid + 1;
        } else {
            return true;
        }
    }

    return false;
}
